+    pub(super) fn note_evaluation(t: f64, anchor: remus_math::vec::Point2) {
+        EVALUATION_LOG.with(|log| {
+            if let Some(log) = log.borrow_mut().as_mut() {
+                log.logical
+                    .push([t.to_bits(), anchor.x().to_bits(), anchor.y().to_bits()]);
+            }
+        });
+    }
